css:
:root{
  --indigo:#2E2B3F; --cream:#FFE9DA; --oat:#F6F2EB; --sand:#E6D6C3;
  --sage:#7F8D7A; --sage-deep:#4C5A47; --terracotta:#C76B4B; --muted:#6B6676;
  --line:rgba(46,43,63,.14); --line-strong:rgba(46,43,63,.5);
  --ease:cubic-bezier(.23,1,.32,1);
  --serif:"Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,serif;
  --sans:"Segoe UI Variable Text","Segoe UI","SF Pro Text","Helvetica Neue",system-ui,-apple-system,Arial,sans-serif;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{background:#1b1a26;color:var(--indigo);font-family:var(--sans);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;overflow:hidden}
body.flow{overflow:auto;background:var(--oat)}
.serif{font-family:var(--serif)}
h1,h2,h3{margin:0;font-family:var(--serif)}
svg{display:block}

/* ====== STAGE (modo apresentação 1280x720) ====== */
#stage{position:absolute;left:0;top:0;width:1280px;height:720px;transform-origin:0 0}
.slide{position:absolute;inset:0;display:none;overflow:hidden;background:var(--oat)}
.slide.active{display:block;animation:slide-in 180ms var(--ease)}
@keyframes slide-in{from{opacity:0}to{opacity:1}}
@media (prefers-reduced-motion:reduce){.slide.active{animation:none}}

.badge{position:absolute;right:38px;top:34px;width:77px;height:77px}
.title{position:absolute;left:58px;top:36px;width:1040px;height:86px;display:flex;align-items:center;font-size:44px;font-weight:600;letter-spacing:-.012em;color:var(--indigo)}
.body{position:absolute;left:58px;right:58px;top:150px;bottom:70px}
.foot{position:absolute;left:58px;right:58px;bottom:24px;display:flex;justify-content:space-between;padding-top:12px;border-top:1px solid var(--line);font-size:11.5px;letter-spacing:.16em;color:var(--muted)}
.foot .pn{letter-spacing:0;font-variant-numeric:tabular-nums}

/* capa */
.slide.cover{background:var(--indigo)}
.cover .logo{position:absolute;right:84px;top:34px;width:182px}
.cover .kicker{position:absolute;left:86px;top:222px;font-size:22px;font-weight:600;letter-spacing:.03em;color:var(--terracotta)}
.cover h1{position:absolute;left:86px;top:268px;font-size:104px;font-weight:600;letter-spacing:-.02em;color:var(--terracotta);line-height:1.1}
.cover .month{position:absolute;left:86px;top:436px;width:560px;padding-top:26px;border-top:1px solid rgba(230,214,195,.28);font-family:var(--serif);font-size:30px;color:var(--sand)}
.cover .period{position:absolute;left:86px;top:512px;font-size:18px;color:var(--sand);opacity:.72}
/* divisor */
.divider .dv{position:absolute;left:86px;top:254px}
.dv-num{font-family:var(--serif);font-size:30px;font-weight:500;letter-spacing:.06em;color:var(--terracotta);margin-bottom:10px}
.dv-title{font-size:92px;font-weight:600;letter-spacing:-.02em;color:var(--indigo);line-height:1.08}
/* encerramento */
.slide.closing{background:var(--indigo)}
.closing img{position:absolute;left:50%;top:50%;width:422px;transform:translate(-50%,-50%)}

/* ====== componentes ====== */
.card{background:transparent;border:0;border-top:1px solid var(--line-strong);border-radius:0;box-shadow:none}
.circ{display:flex;align-items:center;justify-content:flex-start;flex:none;color:var(--terracotta);background:none;border-radius:0}
.circ svg{width:100%;height:100%}
.grid{display:grid;gap:34px 56px}
.g2{grid-template-columns:1fr 1fr}.g3{grid-template-columns:repeat(3,1fr)}.g4{grid-template-columns:repeat(4,1fr);gap:34px 40px}

.kcard{padding:20px 0 0;height:210px}
.k-top{display:flex;align-items:center;gap:12px}
.k-top .circ{width:24px;height:24px}
.k-label{font-size:17px;font-weight:600;color:var(--muted)}
.k-val{font-family:var(--serif);font-size:64px;font-weight:500;margin-top:26px;line-height:1;letter-spacing:-.02em;font-variant-numeric:lining-nums}
.k-cap{font-size:16px;color:var(--muted);margin-top:12px}
.kcard.sm{padding:20px 0 0;height:200px}
.kcard.sm .circ{width:26px;height:26px}
.kcard.sm .k-val{font-size:46px;margin-top:24px}
.kcard.sm .k-lab{font-size:17px;color:var(--muted);margin-top:10px}
.kcard.att .k-val{color:var(--terracotta)}

/* resumo */
.obj{font-size:24px;font-weight:600;margin-top:4px}
.obj .t{color:var(--terracotta)}
.sub{font-size:19px;color:var(--muted);margin-top:26px}
.channels{display:grid;grid-template-columns:1fr 1fr;gap:64px;margin-top:40px;padding:0}
.ch{text-align:left;display:flex;flex-direction:column;align-items:flex-start;border-top:1px solid var(--line-strong);padding-top:30px}
.ch .circ{width:64px;height:64px;margin-bottom:26px;color:var(--indigo)}
.ch b{font-family:var(--serif);font-size:34px;font-weight:600}
.ch span:not(.circ){font-size:18px;color:var(--muted);margin-top:8px}

/* chevrons */
.chev-stage{position:relative;height:470px}
.chev-item{position:absolute;top:191px;width:288px;height:168px}
.chev-bg{position:absolute;inset:0;width:100%;height:100%}
.chev-bg polygon{fill:#F7E6D8;stroke:none}
.chev-stage>.chev-item:nth-child(5) .chev-bg polygon{fill:#F2D9C6}
.chev-stage>.chev-item:nth-child(6) .chev-bg polygon{fill:#ECCBB3}
.chev-stage>.chev-item:nth-child(7) .chev-bg polygon{fill:#E4BA9E}
.chev-stage>.chev-item:nth-child(8) .chev-bg polygon{fill:var(--indigo)}
.chev-in{position:absolute;left:calc(50% - 0px);top:0;transform:translateX(-50%);width:200px;height:168px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:6px}
.chev-item.first .chev-in{left:calc(50% - 21px)}
.chev-in .ic{width:34px;height:34px;color:var(--terracotta)}
.chev-in b{font-size:16px;font-weight:600;letter-spacing:.01em}
.chev-in .val{font-family:var(--serif);font-size:30px;font-weight:600;white-space:nowrap;letter-spacing:-.01em;font-variant-numeric:lining-nums}
body:not(.flow) .chev-stage>.chev-item:nth-child(8) .chev-in{color:#fff}
body:not(.flow) .chev-stage>.chev-item:nth-child(8) .ic{color:var(--sand)}
.chev-var{position:absolute;top:187px;left:0;width:100%;text-align:center;font-size:22px;color:var(--muted)}
.chev-var small{display:none}
.chev-legend{position:absolute;left:10px;top:431px;font-size:15px;color:var(--muted)}
.chev-note{position:absolute;right:0;top:431px;font-size:15px;color:var(--muted)}
.brackets{position:absolute;left:0;top:0}
.b-label{position:absolute;transform:translateX(-50%);text-align:center;font-size:22px;font-weight:600;line-height:1.2;font-variant-numeric:lining-nums}
.b-label small{display:block;font-size:15px;font-weight:400;color:var(--muted)}
.pills{display:none}

/* tabelas */
.tw{overflow-x:auto}
table.tb{border-collapse:collapse;width:100%;font-size:17px;font-variant-numeric:tabular-nums lining-nums}
table.tb th{background:transparent;font-weight:600;font-size:14px;letter-spacing:.04em;color:var(--muted);border:0;border-bottom:1.5px solid var(--line-strong);padding:10px 12px;text-align:right}
table.tb td{background:transparent;border:0;border-bottom:1px solid var(--line);padding:11px 12px;text-align:right}
table.tb th:first-child,table.tb td:first-child{text-align:left}
table.tb td:first-child{font-weight:600}
table.tb td.m{color:var(--muted)}
table.tb tr.tot td{background:transparent;font-weight:700;border-top:1.5px solid var(--line-strong)}
.evo-wrap{height:300px}
.evo-wrap svg{width:100%;height:100%}
.evo-wrap svg text{font-size:12.5px}
.evo-wrap svg line[stroke="#E6D6C3"]{stroke:rgba(46,43,63,.12);stroke-dasharray:2 5}
.evo-wrap svg rect{rx:3}
.evo-wrap svg circle{stroke:var(--oat);stroke-width:2.5}
.evo-table{margin-top:14px}
.evo-table table.tb td,.evo-table table.tb th{padding:7px 12px}

/* retenção */
.ret{display:grid;grid-template-columns:420px 1fr;gap:56px}
.ret .col{display:flex;flex-direction:column;gap:34px}
.callout{padding:20px 0 0;height:190px}
.callout .k-top .circ{width:24px;height:24px}
.callout .k-label{font-size:17px;font-weight:600;color:var(--indigo);line-height:1.2}
.callout .k-label small{display:block;font-size:14px;font-weight:400;color:var(--muted)}
.callout .k-val{color:var(--terracotta);font-size:60px;margin-top:20px}
.callout .k-cap{font-size:16px;margin-top:8px}
.chart-card{padding:20px 0 0;height:414px}
.chart-card h3{font-family:var(--sans);font-size:17px;font-weight:600;color:var(--muted)}
.bars{margin-top:36px;display:flex;flex-direction:column;gap:34px}
.bar-row{display:grid;grid-template-columns:90px 1fr 92px;align-items:center;gap:16px;font-size:18px}
.bar-track{height:14px;background:rgba(46,43,63,.08);border-radius:99px;overflow:hidden}
.bar-fill{height:100%;background:var(--indigo);border-radius:99px}
.bar-val{font-family:var(--serif);font-size:26px;font-weight:600;text-align:right;font-variant-numeric:lining-nums}

/* criativos */
.crea{display:grid;grid-template-columns:repeat(3,1fr);gap:40px}
.frame{position:relative;height:288px;background:var(--sand);border-radius:6px;display:flex;align-items:center;justify-content:center;text-align:center;color:var(--muted);font-size:18px;line-height:1.4;overflow:hidden}
.frame img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.rank{position:absolute;left:14px;top:14px;right:auto;min-width:44px;padding:6px 14px;border-radius:99px;background:var(--indigo);color:#fff;font-size:15px;font-weight:600;display:flex;align-items:center;justify-content:center;z-index:1}
.crea table.tb{margin-top:20px}

/* perfil */
.perfil{display:grid;grid-template-columns:repeat(5,1fr);gap:36px;margin-top:40px}
.pf{width:auto;text-align:left;border-top:1px solid var(--line-strong);padding-top:26px}
.pf .circ{width:48px;height:48px;margin:0 0 30px}
.pf .v{font-family:var(--serif);font-size:36px;font-weight:600;line-height:1.1;font-variant-numeric:lining-nums}
.pf .c{font-size:17px;color:var(--muted);margin-top:12px}
.pre .kcard{height:250px}
.pre .k-val{font-size:72px;margin-top:34px}

/* funil */
.fun{padding:0}
.fun-head,.fun-row{display:grid;grid-template-columns:300px 110px 1fr 150px 190px;align-items:center;column-gap:16px}
.fun-head{font-size:12.5px;font-weight:600;letter-spacing:.14em;color:var(--muted);padding-bottom:12px;border-bottom:1.5px solid var(--line-strong)}
.fun-head span:nth-child(4){text-align:center}.fun-head span:nth-child(5),.fun-row .cost{text-align:right}
.fun-row{height:72px;border-bottom:1px solid var(--line)}
.fun-row .lb{font-size:21px;font-weight:600}
.fun-row .nv{font-family:var(--serif);font-size:34px;font-weight:600;font-variant-numeric:lining-nums}
.fun-row .tr{height:10px;border-radius:99px;background:rgba(46,43,63,.08);overflow:hidden}
.fun-row .fl{height:100%;border-radius:99px;background:var(--indigo);min-width:10px}
.fun-row .rt{text-align:center;font-size:21px;font-weight:600;color:var(--terracotta)}
.fun-row .cost{font-size:18px;color:var(--muted)}

/* foco */
.foco .card{height:190px;padding:22px 0 0;display:flex;gap:26px}
.foco .n{font-family:var(--serif);font-size:46px;font-weight:500;color:var(--terracotta);line-height:1;font-variant-numeric:lining-nums}
.foco .tx{font-size:21px;line-height:1.4}

/* navegação */
.nav{position:fixed;left:50%;bottom:10px;transform:translateX(-50%);display:flex;align-items:center;gap:4px;background:transparent;border:0;border-radius:99px;padding:3px 6px;color:#fff;mix-blend-mode:difference;font-size:13px;z-index:10;opacity:.5;transition:opacity 160ms var(--ease)}
.nav:hover{opacity:1}
.nav button{all:unset;cursor:pointer;width:30px;height:30px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:19px;line-height:1}
.nav button:hover{background:rgba(255,255,255,.18)}
.nav button:active{transform:scale(.94)}
.nav .ct{min-width:56px;text-align:center;font-variant-numeric:tabular-nums}
body.flow .nav{display:none}

/* ====== MODO FLUXO (celular / telas estreitas) ====== */
body.flow #stage{position:static;width:auto;height:auto;transform:none!important}
body.flow .slide{position:relative;display:block;inset:auto;height:auto;padding:26px 18px 28px;border-bottom:10px solid var(--sand);animation:none}
body.flow .slide.cover{padding:60px 22px 56px;min-height:70vh;display:flex;flex-direction:column;justify-content:center;border-bottom:0}
body.flow .cover .logo{position:static;width:120px;margin:0 0 36px auto}
body.flow .cover .kicker,body.flow .cover h1,body.flow .cover .month,body.flow .cover .period{position:static}
body.flow .cover .kicker{font-size:18px}
body.flow .cover h1{font-size:52px;margin:6px 0 16px}
body.flow .cover .month{font-size:22px;width:auto;padding-top:18px}body.flow .cover .period{font-size:14px;margin-top:8px}
body.flow .badge{position:absolute;right:16px;top:16px;width:46px;height:46px}
body.flow .title{position:static;width:auto;height:auto;font-size:28px;padding:34px 56px 16px 0;display:block;line-height:1.15}
body.flow .body{position:static}
body.flow .foot{display:none}
body.flow .slide.divider{padding:54px 22px 50px}
body.flow .divider .dv{position:static}
body.flow .dv-title{font-size:44px}body.flow .dv-num{font-size:20px}
body.flow .slide.closing{padding:60px 20px;border-bottom:0}
body.flow .closing img{position:static;width:min(300px,80%);transform:none;margin:0 auto}
body.flow .grid,body.flow .g2,body.flow .g3{grid-template-columns:1fr;gap:6px}
body.flow .g4{grid-template-columns:1fr 1fr;gap:8px 20px}
body.flow .kcard,body.flow .kcard.sm,body.flow .callout{height:auto;padding:18px 0 20px}
body.flow .k-val{font-size:40px;margin-top:14px}
body.flow .kcard.sm .k-val{font-size:28px;margin-top:14px}
body.flow .k-top .circ,body.flow .kcard.sm .circ{width:22px;height:22px}
body.flow .k-label{font-size:16px}
body.flow .obj{font-size:19px}body.flow .sub{font-size:16px;margin-top:14px}
body.flow .channels{grid-template-columns:1fr;gap:24px;padding:0;margin-top:22px}
body.flow .ch{padding-top:22px}
body.flow .ch .circ{width:52px;height:52px;margin-bottom:16px}
body.flow .ch b{font-size:26px}
body.flow .chev-stage{height:auto;display:flex;flex-direction:column;gap:10px;padding-top:6px}
body.flow .brackets,body.flow .b-label,body.flow .chev-bg{display:none}
body.flow .chev-item{position:relative;top:auto;left:auto!important;width:100%;height:auto;background:#fff;border:1px solid var(--line);border-radius:10px;padding:14px 16px;display:flex;align-items:center;gap:14px}
body.flow .chev-in,body.flow .chev-item.first .chev-in{position:static;left:auto;transform:none;width:auto;height:auto;flex-direction:row;gap:14px;flex:1;text-align:left;justify-content:flex-start}
body.flow .chev-in .ic{width:28px;height:28px}
body.flow .chev-in b{font-size:16px;flex:1}
body.flow .chev-in .val{font-size:22px}
body.flow .chev-var{position:static;width:auto;font-size:15px}
body.flow .chev-var small{display:inline;font-weight:400}
body.flow .chev-legend,body.flow .chev-note{position:static;display:block;margin-top:6px;font-size:13px;text-align:left}
body.flow .pills{display:flex;gap:10px;flex-wrap:wrap;margin-top:6px}
body.flow .pills span{background:var(--cream);border-radius:99px;padding:6px 14px;font-size:14px;font-weight:600}
body.flow .evo-wrap{height:auto}
body.flow .evo-wrap svg{min-width:640px;height:auto}
body.flow .ret{grid-template-columns:1fr;gap:14px}
body.flow .ret .col{gap:6px}
body.flow .chart-card{height:auto;padding:18px 0 0}
body.flow .bars{gap:24px;margin-top:22px}
body.flow .bar-row{grid-template-columns:70px 1fr 64px;font-size:15px}
body.flow .bar-val{font-size:20px}
body.flow .crea{grid-template-columns:1fr;gap:30px}
body.flow .frame{height:220px}
body.flow .perfil{grid-template-columns:1fr 1fr;gap:26px 22px;margin-top:20px}
body.flow .pf{padding-top:20px}
body.flow .pf .circ{width:40px;height:40px;margin-bottom:18px}
body.flow .pf .v{font-size:26px}body.flow .pf .c{font-size:14px}
body.flow .pre .kcard{height:auto}body.flow .pre .k-val{font-size:44px;margin-top:14px}
body.flow .fun{padding:0}
body.flow .fun-head{display:none}
body.flow .fun-row{height:auto;grid-template-columns:1fr auto;row-gap:8px;padding:14px 0}
body.flow .fun-row .lb{font-size:17px}
body.flow .fun-row .nv{font-size:26px;text-align:right}
body.flow .fun-row .tr{grid-column:1/-1}
body.flow .fun-row .rt{text-align:left;font-size:16px}
body.flow .fun-row .cost{font-size:14px}
body.flow .foco .card{height:auto;padding:18px 0 20px;gap:18px}
body.flow .foco .n{font-size:34px}body.flow .foco .tx{font-size:16px}

/* ====== IMPRESSÃO ====== */
@media print{
  @page{size:1280px 720px;margin:0}
  html,body{background:#fff;overflow:visible}
  .nav{display:none}
  #stage{position:static!important;transform:none!important;width:1280px;height:auto}
  .slide{display:block!important;position:relative!important;width:1280px;height:720px;page-break-after:always;break-after:page;overflow:hidden;animation:none!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}
}
